# A message stays inside its school: the student is in the homework's school
# (a student's school is its class's, which a CHECK cannot reach), and a
# teacher's message is written by the teacher who set the homework. The
# trigger guards every insert and every change of those columns.
THREAD_SQL = """
CREATE FUNCTION main_homeworkmessage_in_thread() RETURNS trigger AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM main_homework h
        JOIN main_student s ON s.id = NEW.student_id
        JOIN main_classinfo c ON c.id = s.class_info_id
        WHERE h.id = NEW.homework_id
          AND c.school_id = h.school_id
          AND (NEW.staff_id IS NULL OR NEW.staff_id = h.staff_id)
    ) THEN
        RAISE EXCEPTION 'message on homework % is not between its teacher and a student of its school',
            NEW.homework_id USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER main_homeworkmessage_in_thread
BEFORE INSERT OR UPDATE OF homework_id, student_id, staff_id ON main_homeworkmessage
FOR EACH ROW EXECUTE FUNCTION main_homeworkmessage_in_thread();
"""

